125	// ── Private helpers ────────────────────────────────────────────────────────────
126	
127	fn is_directory_empty(path: &Path) -> Result<bool, String> {
128	    if !path.exists() {
129	        return Ok(true);
130	    }
131	    let mut entries = fs::read_dir(path).map_err(|err| err.to_string())?;
132	    Ok(entries.next().is_none())
133	}
134	
135	fn copy_dir_recursive(from: &Path, to: &Path) -> Result<(), String> {
136	    if !to.exists() {
137	        fs::create_dir_all(to).map_err(|err| err.to_string())?;
138	    }
139	    for entry in fs::read_dir(from).map_err(|err| err.to_string())? {
140	        let entry = entry.map_err(|err| err.to_string())?;
141	        let source = entry.path();
142	        let target = to.join(entry.file_name());
143	        let metadata = entry.metadata().map_err(|err| err.to_string())?;
144	        if metadata.is_dir() {
145	            copy_dir_recursive(&source, &target)?;
146	        } else if metadata.is_file() {
147	            if let Some(parent) = target.parent() {
148	                fs::create_dir_all(parent).map_err(|err| err.to_string())?;
149	            }
150	            fs::copy(&source, &target).map_err(|err| err.to_string())?;
151	        }
152	    }
153	    Ok(())
154	}
155	
156	/// Move directory contents via rename, falling back to copy+delete.
157	fn move_dir_contents(source: &Path, destination: &Path) -> Result<(), String> {
158	    if source == destination {
159	        return Ok(());
160	    }
161	    if !source.exists() {
162	        fs::create_dir_all(destination).map_err(|err| err.to_string())?;
163	        return Ok(());
164	    }
165	    if destination.exists() {
166	        if !is_directory_empty(destination)? {
167	            return Err(format!(
168	                "Destination is not empty: {}",
169	                destination.to_string_lossy()
170	            ));
171	        }
172	    } else if let Some(parent) = destination.parent() {
173	        fs::create_dir_all(parent).map_err(|err| err.to_string())?;
174	    }
175	
176	    if let Err(rename_error) = fs::rename(source, destination) {
177	        copy_dir_recursive(source, destination)?;
178	        fs::remove_dir_all(source).map_err(|err| {
179	            format!(
180	                "Failed to remove source after copy ({}): {}",
181	                source.to_string_lossy(),
182	                err
183	            )
184	        })?;
185	        println!(
186	            "[profiles] fallback copy used while moving profile root (rename failed: {})",
187	            rename_error
188	        );
189	    }
190	    Ok(())
191	}
192	
193	fn sanitize_archive_segment(raw: &str, fallback: &str) -> String {
194	    let mut sanitized = String::new();
195	    let mut previous_dash = false;
196	    for ch in raw.trim().chars() {
197	        if ch.is_ascii_alphanumeric() || ch == '-' || ch == '_' {
198	            sanitized.push(ch.to_ascii_lowercase());
199	            previous_dash = false;
200	        } else if !previous_dash && !sanitized.is_empty() {
201	            sanitized.push('-');
202	            previous_dash = true;
203	        }
204	    }
205	    let compact = sanitized.trim_matches('-').to_string();
206	    if compact.is_empty() {
207	        fallback.to_string()
208	    } else {
209	        compact
210	    }
211	}
212	
213	fn join_zip_path(parent: &str, child: &str) -> String {
214	    if parent.is_empty() {
215	        child.to_string()
216	    } else {
217	        format!("{}/{}", parent.trim_end_matches('/'), child)
218	    }
219	}
220	
221	fn add_path_to_zip(
222	    zip: &mut zip::ZipWriter<fs::File>,
223	    source_path: &Path,
224	    zip_path: &str,
225	    file_count: &mut usize,
226	    total_bytes: &mut u64,
227	) -> Result<(), String> {
228	    let file_metadata = fs::symlink_metadata(source_path).map_err(|error| {
229	        format!(
230	            "Failed to read metadata for {}: {}",
231	            source_path.to_string_lossy(),
232	            error
233	        )
234	    })?;
235	    if file_metadata.file_type().is_symlink() {
236	        return Ok(());
237	    }
238	
239	    let file_options = FileOptions::default()
240	        .compression_method(zip::CompressionMethod::Deflated)
241	        .unix_permissions(0o644);
242	    let directory_options = FileOptions::default()
243	        .compression_method(zip::CompressionMethod::Stored)
244	        .unix_permissions(0o755);
245	
246	    let normalized_zip_path = zip_path.replace('\\', "/");
247	    if file_metadata.is_dir() {
248	        let mut directory_entry = normalized_zip_path.trim_end_matches('/').to_string();
249	        if !directory_entry.is_empty() {
250	            directory_entry.push('/');
251	            zip.add_directory(&directory_entry, directory_options)
252	                .map_err(|error| error.to_string())?;
253	        }
254	        let mut entries = fs::read_dir(source_path)
255	            .map_err(|error| {
256	                format!(
257	                    "Failed to read {}: {}",
258	                    source_path.to_string_lossy(),
259	                    error
260	                )
261	            })?
262	            .collect::<Result<Vec<_>, _>>()
263	            .map_err(|error| error.to_string())?;
264	        entries.sort_by_key(|entry| entry.file_name());
265	        for entry in entries {
266	            let entry_name = entry.file_name().to_string_lossy().to_string();
267	            let child_zip_path = join_zip_path(&normalized_zip_path, &entry_name);
268	            add_path_to_zip(zip, &entry.path(), &child_zip_path, file_count, total_bytes)?;
269	        }
270	        return Ok(());
271	    }
272	
273	    if !file_metadata.is_file() {
274	        return Ok(());
275	    }
276	
277	    zip.start_file(&normalized_zip_path, file_options)
278	        .map_err(|error| error.to_string())?;
279	    let mut input = fs::File::open(source_path).map_err(|error| {
280	        format!(
281	            "Failed to read {}: {}",
282	            source_path.to_string_lossy(),
283	            error
284	        )
285	    })?;
286	    let copied = std::io::copy(&mut input, zip).map_err(|error| {
287	        format!(
288	            "Failed to archive {}: {}",
289	            source_path.to_string_lossy(),
290	            error
291	        )
292	    })?;
293	    *file_count += 1;
294	    *total_bytes += copied;
295	    Ok(())
296	}
297	
298	fn documents_dir(app: &tauri::AppHandle) -> Result<PathBuf, String> {
299	    if let Ok(path) = app.path().document_dir() {
300	        return Ok(path);
301	    }
302	
303	    let app_data = app_data_dir(app)?;
304	    let Some(container_root) = app_data
305	        .parent()
306	        .and_then(Path::parent)
307	        .and_then(Path::parent)
308	    else {
309	        return Err("Failed to resolve the app Documents directory.".to_string());
310	    };
311	    Ok(container_root.join("Documents"))
312	}
313	
314	fn copy_path_with_stats(
315	    from: &Path,
316	    to: &Path,
317	    file_count: &mut usize,
318	    total_bytes: &mut u64,
319	) -> Result<(), String> {
320	    let metadata = fs::symlink_metadata(from).map_err(|err| err.to_string())?;
321	    if metadata.file_type().is_symlink() {
322	        return Ok(());
323	    }
324	
325	    if metadata.is_dir() {
326	        fs::create_dir_all(to).map_err(|err| err.to_string())?;
327	        let mut entries = fs::read_dir(from)
328	            .map_err(|err| err.to_string())?
329	            .collect::<Result<Vec<_>, _>>()
330	            .map_err(|err| err.to_string())?;
331	        entries.sort_by_key(|entry| entry.file_name());
332	        for entry in entries {
333	            let target = to.join(entry.file_name());
334	            copy_path_with_stats(&entry.path(), &target, file_count, total_bytes)?;
335	        }
336	        return Ok(());
337	    }
338	
339	    if !metadata.is_file() {
340	        return Ok(());
341	    }
342	
343	    if let Some(parent) = to.parent() {
344	        fs::create_dir_all(parent).map_err(|err| err.to_string())?;
345	    }
346	    fs::copy(from, to).map_err(|err| err.to_string())?;
347	    *file_count += 1;
348	    *total_bytes += metadata.len();
349	    Ok(())
350	}
351	
352	/// Resolve the notes root using env vars / cwd / app data fallback.
353	pub(crate) fn legacy_notes_root(app: &tauri::AppHandle) -> Result<PathBuf, String> {
354	    if let Ok(path) = std::env::var("NOTES_ROOT") {
355	        let root = PathBuf::from(path);
356	        if root.exists() {
357	            return Ok(root);
358	        }
359	    }
360	
361	    let cwd = std::env::current_dir().map_err(|err| err.to_string())?;
362	    let direct = cwd.join("notes");
363	    if direct.exists() {
364	        return Ok(direct);
365	    }
366	    let parent = cwd.join("..").join("notes");
367	    if parent.exists() {
368	        return Ok(parent);
369	    }
370	
371	    let app_data = app_data_dir(app)?;
372	    let root = app_data.join("notes");
373	    if !root.exists() {
374	        fs::create_dir_all(&root).map_err(|err| err.to_string())?;
375	    }
376	    Ok(root)
377	}
378	
379	fn normalize_profile_name(name: &str) -> String {
380	    let trimmed = name.trim();
381	    if trimmed.is_empty() {
382	        "Profile".to_string()
383	    } else {
384	        trimmed.to_string()
385	    }
386	}
387	
388	fn normalize_profile_description(description: &str) -> String {
389	    description.trim().to_string()
390	}
391	
392	fn profile_name_from_id(id: &str) -> String {
393	    let words = id
394	        .split(|ch: char| ch == '-' || ch == '_' || ch.is_whitespace())
395	        .filter_map(|segment| {
396	            let trimmed = segment.trim();
397	            if trimmed.is_empty() {
398	                return None;
399	            }
400	            let mut chars = trimmed.chars();
401	            let first = chars.next()?;
402	            let mut title = String::new();
403	            title.push(first.to_ascii_uppercase());
404	            title.extend(chars);
405	            Some(title)
406	        })
407	        .collect::<Vec<_>>();
408	    if words.is_empty() {
409	        "Profile".to_string()
410	    } else {
411	        words.join(" ")
412	    }
413	}
414	
415	fn push_normalized_profile(
416	    app: &tauri::AppHandle,
417	    mut profile: NotesProfileEntry,
418	    seen_ids: &mut HashSet<String>,
419	    seen_roots: &mut HashSet<String>,
420	    profiles: &mut Vec<NotesProfileEntry>,
421	) -> Result<(), String> {
422	    let id = profile.id.trim().to_string();
423	    if id.is_empty() || !seen_ids.insert(id.clone()) {
424	        return Ok(());
425	    }
426	
427	    profile.id = id.clone();
428	    profile.name = normalize_profile_name(&profile.name);
429	    profile.description = normalize_profile_description(&profile.description);
430	    if profile.notes_root.trim().is_empty() {
431	        profile.notes_root = profile_root_for_id(app, &id)?.to_string_lossy().to_string();
432	    }
433	
434	    let root = PathBuf::from(profile.notes_root.trim());
435	    if !root.exists() {
436	        fs::create_dir_all(&root).map_err(|err| err.to_string())?;
437	    }
438	    ensure_system_folders(&root)?;
439	
440	    let normalized_root = root.to_string_lossy().to_string();
441	    if !seen_roots.insert(normalized_root.clone()) {
442	        return Ok(());
443	    }
444	
445	    profile.notes_root = normalized_root;
446	    profiles.push(profile);
447	    Ok(())
448	}
449	
450	fn discover_filesystem_profiles(
451	    app: &tauri::AppHandle,
452	    seen_ids: &HashSet<String>,
453	    seen_roots: &HashSet<String>,
454	) -> Result<Vec<NotesProfileEntry>, String> {
455	    let profiles_root = app_data_dir(app)?.join("profiles");
456	    if !profiles_root.exists() {
457	        return Ok(Vec::new());
458	    }
459	
460	    let mut entries = fs::read_dir(&profiles_root)
461	        .map_err(|err| err.to_string())?
462	        .collect::<Result<Vec<_>, _>>()
463	        .map_err(|err| err.to_string())?;
464	    entries.sort_by_key(|entry| entry.file_name());
465	
466	    let mut discovered = Vec::new();
467	    for entry in entries {
468	        let metadata = entry.metadata().map_err(|err| err.to_string())?;
469	        if !metadata.is_dir() {
470	            continue;
471	        }
472	
473	        let id = entry.file_name().to_string_lossy().trim().to_string();
474	        if id.is_empty() || seen_ids.contains(&id) {
475	            continue;
476	        }
477	
478	        let notes_root = entry.path().join("notes");
479	        if !notes_root.is_dir() {
480	            continue;
481	        }
482	
483	        let notes_root_string = notes_root.to_string_lossy().to_string();
484	        if seen_roots.contains(&notes_root_string) {
485	            continue;
486	        }
487	
488	        discovered.push(NotesProfileEntry {
489	            id: id.clone(),
490	            name: profile_name_from_id(&id),
491	            description: String::new(),
492	            notes_root: notes_root_string,
493	        });
494	    }
495	
496	    Ok(discovered)
497	}
498	
499	/// Generate a URL-safe id from a profile name.
500	fn slugify_profile_id(name: &str) -> String {
501	    let mut slug = String::new();
502	    let mut last_dash = false;
503	    for ch in name.chars() {
504	        let lower = ch.to_ascii_lowercase();
505	        if lower.is_ascii_alphanumeric() {
506	            slug.push(lower);
507	            last_dash = false;
508	            continue;
509	        }
510	        if !last_dash && !slug.is_empty() {
511	            slug.push('-');
512	            last_dash = true;
513	        }
514	    }
515	    let compact = slug.trim_matches('-').to_string();
516	    if compact.is_empty() {
517	        "profile".to_string()
518	    } else {
519	        compact
520	    }
521	}
522	
523	// ── State management ───────────────────────────────────────────────────────────
524	
525	/// Build a default profiles state rooted at the legacy notes directory.
526	pub(crate) fn default_profiles_state(app: &tauri::AppHandle) -> Result<NotesProfilesFile, String> {
527	    let legacy_root = legacy_notes_root(app)?;
528	    if !legacy_root.exists() {
529	        fs::create_dir_all(&legacy_root).map_err(|err| err.to_string())?;
530	    }
531	    Ok(NotesProfilesFile {
532	        active_profile_id: "default".to_string(),
533	        profiles: vec![NotesProfileEntry {
534	            id: "default".to_string(),
535	            name: "Default".to_string(),
536	            description: String::new(),
537	            notes_root: legacy_root.to_string_lossy().to_string(),
538	        }],
539	    })
540	}
541	
542	pub(crate) fn write_profiles_state(
543	    app: &tauri::AppHandle,
544	    state: &NotesProfilesFile,
545	) -> Result<(), String> {
546	    let path = profiles_file_path(app)?;
547	    let content = serde_json::to_string_pretty(state).map_err(|err| err.to_string())?;
548	    fs::write(path, content).map_err(|err| err.to_string())
549	}
