551	/// Validate and normalize a profiles state: remove duplicates, fix empty roots.
552	pub(crate) fn normalize_profiles_state(
553	    app: &tauri::AppHandle,
554	    mut state: NotesProfilesFile,
555	) -> Result<NotesProfilesFile, String> {
556	    let mut seen_ids = HashSet::new();
557	    let mut seen_roots = HashSet::new();
558	    let mut profiles = Vec::new();
559	    for profile in state.profiles.drain(..) {
560	        push_normalized_profile(app, profile, &mut seen_ids, &mut seen_roots, &mut profiles)?;
561	    }
562	
563	    if profiles.is_empty() {
564	        for profile in default_profiles_state(app)?.profiles {
565	            push_normalized_profile(app, profile, &mut seen_ids, &mut seen_roots, &mut profiles)?;
566	        }
567	    }
568	
569	    let discovered = discover_filesystem_profiles(app, &seen_ids, &seen_roots)?;
570	    for profile in discovered {
571	        push_normalized_profile(app, profile, &mut seen_ids, &mut seen_roots, &mut profiles)?;
572	    }
573	
574	    let active_profile_id = if profiles
575	        .iter()
576	        .any(|profile| profile.id == state.active_profile_id)
577	    {
578	        state.active_profile_id
579	    } else {
580	        profiles[0].id.clone()
581	    };
582	
583	    Ok(NotesProfilesFile {
584	        active_profile_id,
585	        profiles,
586	    })
587	}
588	
589	fn migrate_legacy_profiles_state(state: LegacyProfilesMigrationFile) -> NotesProfilesFile {
590	    NotesProfilesFile {
591	        active_profile_id: state.active_profile_id,
592	        profiles: state.profiles,
593	    }
594	}
595	
596	/// Load profiles from disk, migrating from legacy format if needed.
597	pub(crate) fn ensure_profiles_state(app: &tauri::AppHandle) -> Result<NotesProfilesFile, String> {
598	    let path = profiles_file_path(app)?;
599	    if path.exists() {
600	        let content = fs::read_to_string(&path).map_err(|err| err.to_string())?;
601	        return match serde_json::from_str::<NotesProfilesFile>(&content) {
602	            Ok(parsed) => {
603	                let normalized = normalize_profiles_state(app, parsed.clone())?;
604	                if normalized != parsed {
605	                    write_profiles_state(app, &normalized)?;
606	                }
607	                Ok(normalized)
608	            }
609	            Err(_) => {
610	                let state = normalize_profiles_state(app, default_profiles_state(app)?)?;
611	                write_profiles_state(app, &state)?;
612	                Ok(state)
613	            }
614	        };
615	    }
616	
617	    let legacy_path = legacy_profiles_file_path(app)?;
618	    if legacy_path.exists() {
619	        let content = fs::read_to_string(&legacy_path).map_err(|err| err.to_string())?;
620	        let migrated =
621	            if let Ok(parsed_profiles) = serde_json::from_str::<NotesProfilesFile>(&content) {
622	                parsed_profiles
623	            } else if let Ok(parsed_legacy) =
624	                serde_json::from_str::<LegacyProfilesMigrationFile>(&content)
625	            {
626	                migrate_legacy_profiles_state(parsed_legacy)
627	            } else {
628	                NotesProfilesFile::default()
629	            };
630	        if !migrated.profiles.is_empty() {
631	            let normalized = normalize_profiles_state(app, migrated)?;
632	            write_profiles_state(app, &normalized)?;
633	            let _ = fs::remove_file(&legacy_path);
634	            return Ok(normalized);
635	        }
636	    }
637	
638	    let state = normalize_profiles_state(app, default_profiles_state(app)?)?;
639	    write_profiles_state(app, &state)?;
640	    Ok(state)
641	}
