643	pub(crate) fn profiles_snapshot(state: &NotesProfilesFile) -> NotesProfilesSnapshot {
644	    NotesProfilesSnapshot {
645	        active_profile_id: state.active_profile_id.clone(),
646	        profiles: state.profiles.clone(),
