650	pub(crate) fn find_profile<'a>(
651	    state: &'a NotesProfilesFile,
652	    profile_id: &str,
653	) -> Option<&'a NotesProfileEntry> {
654	    state
655	        .profiles
656	        .iter()
657	        .find(|profile| profile.id == profile_id)
658	}
