660	// ── Profile CRUD ───────────────────────────────────────────────────────────────
661	
662	pub(crate) fn set_active_profile_state(
663	    app: &tauri::AppHandle,
664	    profile_id: &str,
665	) -> Result<NotesProfilesFile, String> {
666	    let mut state = ensure_profiles_state(app)?;
667	    let id = profile_id.trim();
668	    if id.is_empty() {
669	        return Err("Profile id is required.".to_string());
670	    }
671	    if find_profile(&state, id).is_none() {
672	        return Err(format!("Profile not found: {}", id));
673	    }
674	    state.active_profile_id = id.to_string();
675	    write_profiles_state(app, &state)?;
676	    Ok(state)
677	}
678	
679	pub(crate) fn create_profile_state(
680	    app: &tauri::AppHandle,
681	    name: &str,
682	    description: Option<&str>,
683	) -> Result<NotesProfilesFile, String> {
684	    let mut state = ensure_profiles_state(app)?;
685	    let profile_name = normalize_profile_name(name);
686	    let base_id = slugify_profile_id(&profile_name);
687	    let existing: HashSet<String> = state
688	        .profiles
689	        .iter()
690	        .map(|profile| profile.id.clone())
691	        .collect();
692	    let mut profile_id = base_id.clone();
693	    let mut suffix = 2usize;
694	    while existing.contains(&profile_id) {
695	        profile_id = format!("{}-{}", base_id, suffix);
696	        suffix += 1;
697	    }
698	
699	    let profile_root = profile_root_for_id(app, &profile_id)?;
700	    if !profile_root.exists() {
701	        fs::create_dir_all(&profile_root).map_err(|err| err.to_string())?;
702	    }
703	
704	    state.profiles.push(NotesProfileEntry {
705	        id: profile_id.clone(),
706	        name: profile_name,
707	        description: normalize_profile_description(description.unwrap_or("")),
708	        notes_root: profile_root.to_string_lossy().to_string(),
709	    });
710	    state.active_profile_id = profile_id;
711	    write_profiles_state(app, &state)?;
712	    Ok(state)
713	}
