715	pub(crate) fn update_profile_state(
716	    app: &tauri::AppHandle,
717	    profile_id: &str,
718	    name: Option<&str>,
719	    description: Option<&str>,
720	) -> Result<NotesProfilesFile, String> {
721	    let mut state = ensure_profiles_state(app)?;
722	    let id = profile_id.trim();
723	    if id.is_empty() {
724	        return Err("Profile id is required.".to_string());
725	    }
726	    let Some(index) = state.profiles.iter().position(|profile| profile.id == id) else {
727	        return Err(format!("Profile not found: {}", id));
728	    };
729	    if let Some(next_name) = name {
730	        state.profiles[index].name = normalize_profile_name(next_name);
731	    }
732	    if let Some(next_description) = description {
733	        state.profiles[index].description = normalize_profile_description(next_description);
734	    }
735	    write_profiles_state(app, &state)?;
736	    Ok(state)
737	}
