739	pub(crate) fn delete_profile_state(
740	    app: &tauri::AppHandle,
741	    profile_id: &str,
742	) -> Result<NotesProfilesFile, String> {
743	    let mut state = ensure_profiles_state(app)?;
744	    let id = profile_id.trim();
745	    if id.is_empty() {
746	        return Err("Profile id is required.".to_string());
747	    }
748	    if state.profiles.len() <= 1 {
749	        return Err("At least one profile must remain.".to_string());
750	    }
751	    let Some(index) = state.profiles.iter().position(|profile| profile.id == id) else {
752	        return Err(format!("Profile not found: {}", id));
753	    };
754	    state.profiles.remove(index);
755	    if state.active_profile_id == id {
756	        let next_active = state
757	            .profiles
758	            .first()
759	            .ok_or_else(|| "At least one profile must remain.".to_string())?;
760	        state.active_profile_id = next_active.id.clone();
761	    }
762	    write_profiles_state(app, &state)?;
763	    Ok(state)
764	}
