766	/// Validate and normalize an absolute notes root path.
767	pub(crate) fn normalize_notes_root_path(notes_root: &str) -> Result<PathBuf, String> {
768	    let trimmed = notes_root.trim();
769	    if trimmed.is_empty() {
770	        return Err("Profile notes root is required.".to_string());
771	    }
772	    let candidate = PathBuf::from(trimmed);
773	    if !candidate.is_absolute() {
774	        return Err("Profile notes root must be an absolute path.".to_string());
775	    }
776	    Ok(candidate)
777	}
