779	/// Change a profile's notes root, moving existing content.
780	pub(crate) fn set_profile_notes_root_state(
781	    app: &tauri::AppHandle,
782	    profile_id: &str,
783	    notes_root: &str,
784	) -> Result<NotesProfilesFile, String> {
785	    let mut state = ensure_profiles_state(app)?;
786	    let id = profile_id.trim();
787	    if id.is_empty() {
788	        return Err("Profile id is required.".to_string());
789	    }
790	    let next_root = normalize_notes_root_path(notes_root)?;
791	    let Some(index) = state.profiles.iter().position(|profile| profile.id == id) else {
792	        return Err(format!("Profile not found: {}", id));
793	    };
794	
795	    let current_root = PathBuf::from(state.profiles[index].notes_root.trim());
796	    if current_root != next_root {
797	        move_dir_contents(&current_root, &next_root)?;
798	    } else if !next_root.exists() {
799	        fs::create_dir_all(&next_root).map_err(|err| err.to_string())?;
800	    }
801	    ensure_system_folders(&next_root)?;
802	
803	    state.profiles[index].notes_root = next_root.to_string_lossy().to_string();
804	    write_profiles_state(app, &state)?;
805	    Ok(state)
806	}
