808	pub(crate) fn create_profiles_backup_zip_impl(
809	    app: &tauri::AppHandle,
810	) -> Result<ProfilesBackupArchive, String> {
811	    let state = ensure_profiles_state(app)?;
812	    let export_root = app_data_dir(app)?.join("exports");
813	    fs::create_dir_all(&export_root).map_err(|error| error.to_string())?;
814	
815	    let timestamp = now_ms().unwrap_or(0);
816	    let archive_name = format!("type-backup-{}.zip", timestamp);
817	    let archive_path = export_root.join(&archive_name);
818	    if archive_path.exists() {
819	        fs::remove_file(&archive_path).map_err(|error| error.to_string())?;
820	    }
821	
822	    let output = fs::File::create(&archive_path).map_err(|error| error.to_string())?;
823	    let mut zip = zip::ZipWriter::new(output);
824	    let metadata_file_options = FileOptions::default()
825	        .compression_method(zip::CompressionMethod::Deflated)
826	        .unix_permissions(0o644);
827	
828	    let snapshot_json = serde_json::to_vec_pretty(&state).map_err(|error| error.to_string())?;
829	    zip.start_file("profiles-state.json", metadata_file_options)
830	        .map_err(|error| error.to_string())?;
831	    zip.write_all(&snapshot_json)
832	        .map_err(|error| error.to_string())?;
833	
834	    let mut file_count = 1usize;
835	    let mut total_bytes = snapshot_json.len() as u64;
836	
837	    for (index, profile) in state.profiles.iter().enumerate() {
838	        let notes_root = PathBuf::from(profile.notes_root.trim());
839	        if !notes_root.exists() {
840	            return Err(format!(
841	                "Profile \"{}\" notes root does not exist: {}",
842	                profile.name,
843	                notes_root.to_string_lossy()
844	            ));
845	        }
846	        let profile_id = sanitize_archive_segment(&profile.id, "profile");
847	        let zip_prefix = format!("profiles/{:02}-{}/notes", index + 1, profile_id);
848	        add_path_to_zip(
849	            &mut zip,
850	            &notes_root,
851	            &zip_prefix,
852	            &mut file_count,
853	            &mut total_bytes,
854	        )?;
855	    }
856	
857	    zip.finish().map_err(|error| error.to_string())?;
858	
859	    Ok(ProfilesBackupArchive {
860	        archive_path: archive_path.to_string_lossy().to_string(),
861	        archive_name,
862	        profile_count: state.profiles.len(),
863	        file_count,
864	        total_bytes,
865	    })
866	}
