876	    let export_path = documents_root.join(&export_name);
877	    fs::create_dir_all(&export_path).map_err(|err| err.to_string())?;
878	
879	    let mut file_count = 0usize;
880	    let mut total_bytes = 0u64;
881	
882	    let profiles_state_path = profiles_file_path(app)?;
883	    if profiles_state_path.exists() {
884	        let target = export_path.join(".notes-profiles.json");
885	        copy_path_with_stats(&profiles_state_path, &target, &mut file_count, &mut total_bytes)?;
886	    }
887	
888	    let security_path = app_data_dir(app)?.join(".notes-security.json");
889	    if security_path.exists() {
890	        let target = export_path.join(".notes-security.json");
891	        copy_path_with_stats(&security_path, &target, &mut file_count, &mut total_bytes)?;
892	    }
893	
894	    let snapshot_json = serde_json::to_vec_pretty(&state).map_err(|err| err.to_string())?;
895	    let snapshot_target = export_path.join("profiles-state.json");
896	    fs::write(&snapshot_target, &snapshot_json).map_err(|err| err.to_string())?;
897	    file_count += 1;
898	    total_bytes += snapshot_json.len() as u64;
899	
900	    for (index, profile) in state.profiles.iter().enumerate() {
901	        let notes_root = PathBuf::from(profile.notes_root.trim());
902	        if !notes_root.exists() {
